-- BREACH-DOCTOR-RETIRE-1 (charter pillar autonomy; issue 1000399).
-- Retire only the two superseded trigger entry points. The issue-age duty now runs as the
-- issue-age-live-doers task/cron (ISSUE-AGE-HEAVY-TICK-DETACH-1); breach diagnosis and
-- remediation run through qnfo-fleet-control breachDoctorTick and its verified
-- qnfo-cloud-ops BREACH-DOCTOR-WATCH-2 second path. Keep both legacy action tables readable:
-- DEPLOY-ALL-MERGES-1 and other consumers still read their history.
-- Live precondition: breaches_auto_remediated_24h=4; the WATCH-2 run and
-- control_registry alternate were verified at 2026-11-01T23:20:55Z.
-- Graph impact for each trigger resolves through qnfo-audit to its existing bound workers;
-- the migration preserves qnfo-audit and both referenced tables.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261102_breach_doctor_retired_triggers
-- Rollback: CREATE TRIGGER IF NOT EXISTS deploy_merge_age_tick AFTER INSERT ON fleet_tick BEGIN INSERT INTO issue_age_replans (issue_id, outcome_was, planned_at_was, age_h) SELECT id, plan_outcome, planned_at, age_h FROM v_issue_age_ladder l WHERE COALESCE((SELECT value FROM ops_config WHERE key = 'issue_age_replan'), 'on') <> 'off' AND l.age_h >= 24 AND l.doer IS NULL AND l.plan_outcome IN ('not-code', 'invalid') AND l.planned_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-24 hours') AND NOT EXISTS (SELECT 1 FROM issue_age_replans r WHERE r.issue_id = l.id AND r.ts > strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-24 hours')) ORDER BY l.age_h DESC LIMIT 12; UPDATE issue_plans SET planned_at = '2000-01-01T00:00:00Z', detail = substr('ISSUE-AGE-24H-1 re-plan (was ' || outcome || ' at ' || planned_at || '): ' || COALESCE(detail, ''), 1, 600) WHERE issue_id IN (SELECT issue_id FROM issue_age_replans WHERE ts >= strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-1 minutes')) AND outcome IN ('not-code', 'invalid') AND planned_at <> '2000-01-01T00:00:00Z'; UPDATE metric_registry SET last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), state = 'MEASURED', last_value = CAST((SELECT COUNT(*) FROM v_issue_age_ladder WHERE breach = 1) AS TEXT) WHERE metric = 'issues_over_24h_no_doer'; UPDATE metric_registry SET last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), state = 'MEASURED', last_value = CAST((SELECT workers_undeployed_over_60m FROM v_merge_reliability) AS TEXT) WHERE metric = 'merges_undeployed_over_60m'; UPDATE metric_registry SET last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), state = 'MEASURED', last_value = CAST((SELECT COALESCE(merge_share_7d, 1) FROM v_merge_reliability) AS TEXT) WHERE metric = 'code_pr_merge_share_7d'; UPDATE metric_registry SET last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), state = 'MEASURED', last_value = CAST((SELECT prs_unmerged_over_120m FROM v_merge_reliability) AS TEXT) WHERE metric = 'code_prs_unmerged_over_120m'; END; CREATE TRIGGER IF NOT EXISTS breach_selfheal_heavy_tick AFTER INSERT ON fleet_tick_heavy BEGIN DELETE FROM breach_selfheal_state; INSERT INTO breach_selfheal_state (check_class, subject, hit, diagnosis, evidence) SELECT check_class, subject, hit, diagnosis, evidence FROM v_breach_selfheal; DELETE FROM breach_selfheal_inputs_state; INSERT INTO breach_selfheal_inputs_state SELECT * FROM v_breach_selfheal_inputs; INSERT INTO breach_selfheal_actions (check_class, subject, action, revert, evidence) SELECT 'errata-rate', 'errata-confirm', 'errata_confirm_max ' || i.errata_confirm_max || ' -> 12', 'ops_config errata_confirm_max = ' || i.errata_confirm_max, CASE WHEN b.hit = 1 THEN 'budget share: ' || b.evidence WHEN i.budget_spent_today >= i.research_daily_neurons THEN 'research budget spent: ' || CAST(i.budget_spent_today AS INTEGER) ELSE 'backlog drained: backlog=' || i.errata_backlog END FROM breach_selfheal_inputs_state i, breach_selfheal_state b WHERE COALESCE((SELECT value FROM ops_config WHERE key = 'breach_selfheal'), 'on') <> 'off' AND b.check_class = 'budget-share' AND i.errata_confirm_max > 12 AND (b.hit = 1 OR i.errata_backlog < 50 OR i.budget_spent_today >= i.research_daily_neurons); UPDATE ops_config SET value = '12', updated_at = datetime('now'), note = substr('BREACH-SELFHEAL-1 lowered at ' || strftime('%Y-%m-%dT%H:%M:%SZ', 'now') || '. ' || COALESCE(note, ''), 1, 600) WHERE key = 'errata_confirm_max' AND COALESCE((SELECT value FROM ops_config WHERE key = 'breach_selfheal'), 'on') <> 'off' AND CAST(value AS INTEGER) > 12 AND ((SELECT hit FROM breach_selfheal_state WHERE check_class = 'budget-share') = 1 OR (SELECT errata_backlog FROM breach_selfheal_inputs_state) < 50 OR (SELECT budget_spent_today >= research_daily_neurons FROM breach_selfheal_inputs_state) = 1); INSERT INTO breach_selfheal_actions (check_class, subject, action, revert, evidence) SELECT 'errata-rate', 'errata-confirm', 'errata_confirm_max ' || i.errata_confirm_max || ' -> ' || MIN(48, MAX(12, i.errata_confirm_max) * 2), 'ops_config errata_confirm_max = ' || i.errata_confirm_max, k.evidence FROM breach_selfheal_inputs_state i, breach_selfheal_state k WHERE COALESCE((SELECT value FROM ops_config WHERE key = 'breach_selfheal'), 'on') <> 'off' AND k.check_class = 'chain-backlog' AND k.subject = 'errata-confirm' AND k.hit = 1 AND i.errata_settled_2h > 0 AND i.errata_confirm_max < 48 AND i.budget_spent_today < i.research_budget_pace_now AND (SELECT hit FROM breach_selfheal_state WHERE check_class = 'budget-share') = 0 AND NOT EXISTS (SELECT 1 FROM breach_selfheal_actions a WHERE a.check_class = 'errata-rate' AND a.ts >= strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-60 minutes')); UPDATE ops_config SET value = CAST(MIN(48, MAX(12, CAST(value AS INTEGER)) * 2) AS TEXT), updated_at = datetime('now'), note = substr('BREACH-SELFHEAL-1 raised at ' || strftime('%Y-%m-%dT%H:%M:%SZ', 'now') || ' (backlog old, budget share fine). ' || COALESCE(note, ''), 1, 600) WHERE key = 'errata_confirm_max' AND CAST(value AS INTEGER) < 48 AND EXISTS (SELECT 1 FROM breach_selfheal_actions a WHERE a.id = (SELECT MAX(id) FROM breach_selfheal_actions WHERE check_class = 'errata-rate') AND a.ts >= strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-1 minutes') AND a.action = 'errata_confirm_max ' || ops_config.value || ' -> ' || MIN(48, MAX(12, CAST(ops_config.value AS INTEGER)) * 2)); INSERT INTO breach_selfheal_actions (check_class, subject, action, revert, evidence) SELECT 'chain-stall', 'research', 'requeued ' || COUNT(*) || ' dead claims at their stage: ' || group_concat(substr(id, 1, 12), ','), 'status researching, claimed_at as before', (SELECT evidence FROM breach_selfheal_state WHERE check_class = 'chain-stall' AND subject = 'research') FROM (SELECT id FROM research_queue WHERE status = 'researching' AND claimed_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-120 minutes') ORDER BY claimed_at LIMIT 6) WHERE COALESCE((SELECT value FROM ops_config WHERE key = 'breach_selfheal'), 'on') <> 'off' AND (SELECT hit FROM breach_selfheal_state WHERE check_class = 'chain-stall' AND subject = 'research') = 1 HAVING COUNT(*) > 0; UPDATE research_queue SET status = CASE WHEN COALESCE(recover_count, 0) < 3 THEN 'queued' ELSE 'wontfix' END, stage = CASE WHEN COALESCE(recover_count, 0) < 3 THEN stage ELSE 'parked' END, recover_count = COALESCE(recover_count, 0) + 1, error = substr('BREACH-SELFHEAL-1 dead claim (no heartbeat since ' || COALESCE(claimed_at, '?') || ', no ok stage fleet-wide in 60 min; revert: status researching): ' || COALESCE(error, ''), 1, 300), claimed_at = NULL WHERE id IN (SELECT id FROM research_queue WHERE status = 'researching' AND claimed_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-120 minutes') ORDER BY claimed_at LIMIT 6) AND COALESCE((SELECT value FROM ops_config WHERE key = 'breach_selfheal'), 'on') <> 'off' AND (SELECT hit FROM breach_selfheal_state WHERE check_class = 'chain-stall' AND subject = 'research') = 1; UPDATE metric_registry SET last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), state = 'MEASURED', last_value = CAST((SELECT hit FROM breach_selfheal_state WHERE check_class = 'chain-stall' AND subject = 'errata-confirm') AS TEXT) WHERE metric = 'errata_confirm_stalled'; UPDATE metric_registry SET last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), state = 'MEASURED', last_value = CAST((SELECT hit FROM breach_selfheal_state WHERE check_class = 'chain-stall' AND subject = 'research') AS TEXT) WHERE metric = 'research_stage_stalled'; UPDATE metric_registry SET last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), state = 'MEASURED', last_value = CAST((SELECT CASE WHEN published_daily_base_7d < 5 THEN 1 ELSE ROUND(published_24h / published_daily_base_7d, 3) END FROM breach_selfheal_inputs_state) AS TEXT) WHERE metric = 'publish_rate_ratio_24h'; UPDATE metric_registry SET last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), state = 'MEASURED', last_value = CAST((SELECT COUNT(*) FROM breach_selfheal_state WHERE check_class = 'post-deploy-errors' AND hit = 1) AS TEXT) WHERE metric = 'post_deploy_error_workers'; UPDATE metric_registry SET last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), state = 'MEASURED', last_value = CAST((SELECT CASE WHEN budget_spent_today > 0 THEN ROUND(budget_members_today * 1.0 / budget_spent_today, 3) ELSE 0 END FROM breach_selfheal_inputs_state) AS TEXT) WHERE metric = 'research_budget_member_share'; END;
-- Closing probe: SELECT 'ok' AS expected, CASE WHEN COUNT(*)=0 THEN 'ok' ELSE group_concat(name) END AS observed FROM sqlite_master WHERE type='trigger' AND name IN ('deploy_merge_age_tick','breach_selfheal_heavy_tick');

CREATE TABLE IF NOT EXISTS bak_20261102_breach_doctor_retired_triggers AS
SELECT name, sql FROM sqlite_master
WHERE type = 'trigger'
  AND name IN ('deploy_merge_age_tick', 'breach_selfheal_heavy_tick');

DROP TRIGGER IF EXISTS deploy_merge_age_tick;
DROP TRIGGER IF EXISTS breach_selfheal_heavy_tick;

INSERT INTO decision_log
  (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'copilot:1000399',
  'The verified breach-doctor case and exercised WATCH-2 path can replace the two legacy trigger entry points; the issue-age task already owns replanning.',
  'BREACH-DOCTOR-RETIRE-1: remove deploy_merge_age_tick and breach_selfheal_heavy_tick while retaining their historical action tables.',
  'qnfo-audit read-only: breaches_auto_remediated_24h=4; breach-doctor:second-path-playbooks last_exercised_at=2026-11-01T23:20:55Z; control_registry alternate_tested_at and the run status were ok. Both trigger impacts resolve through qnfo-audit to existing bound workers.',
  'pending CI apply and the trigger-absence closing probe',
  'two triggers only; issue_age_replans and breach_selfheal_actions and all their rows stay readable',
  'The Rollback header recreates both captured trigger definitions; the backup table remains available.',
  'Issue-age replanning continues through issue-age-live-doers; breach diagnosis and remediation continue through breachDoctorTick and WATCH-2.',
  'Both obsolete trigger names become absent without deleting or altering their history tables.',
  'none',
  'live D1 and graph read; migration/rollback SQLite test'
WHERE NOT EXISTS (
  SELECT 1 FROM decision_log
  WHERE action LIKE 'BREACH-DOCTOR-RETIRE-1:%'
);
